let page='home',selected=1,taskFilter='全部',search='',aiReady=false,searchTimer;const navs=[['home','home','今日工作'],['chat','chat','咨询接待'],['customers','users','客户管理'],['orders','box','订单与售后'],['retention','task','老客经营'],['knowledge','book','产品与知识'],['report','chart','我的业绩']];
