function toast(t){const el=document.getElementById('toast');el.className='toast';el.textContent=t;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>{el.className='';el.textContent=''},3000)}
function customer(id){return state.customers.find(c=>c.id===Number(id))}function avatar(c){return `<div class="avatar" style="background:${c.color}">${c.short}</div>`}function pending(){return state.tasks.filter(t=>!t.done).length}
function shell(){document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('leaf')}</div><div><b>青禾</b><small>ADVISOR WORKSPACE</small></div></div><div class="nav-label">顾问工作空间</div>${navs.map(([id,i,t])=>`<button class="nav ${page===id?'active':''}" data-nav="${id}" title="${t}">${icon(i)}<span>${t}</span>${id==='chat'?'<b class="count">4</b>':''}</button>`).join('')}<div class="sidebar-bottom"><div class="mini-help"><div class="flex">${icon('spark')}<b class="small">让每一次服务更有温度</b></div><p>AI 为你整理信息与建议<br>由你决定下一步行动</p></div><button class="nav" data-action="help">${icon('headphones')}<span>演示指南</span></button><div class="account flex"><div class="avatar">禾</div><div><b class="small">小禾 · 营养顾问</b><p class="small muted" style="margin-top:4px">呜咔实验室服务团队</p></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">工作空间 <span>/　${navs.find(n=>n[0]===page)?.[2]||'今日工作'}</span></div><div class="top-actions"><span class="demo-badge">DEMO · 样例数据 / 模拟 AI</span><button title="查看待办" data-nav="home">${icon('bell')}</button><div class="avatar" style="width:29px;height:29px;font-size:11px">禾</div></div></header><div class="content">${renderPage()}</div></main></div>`;bind();if(page==='chat'){const m=document.querySelector('.chat-messages');m.scrollTop=m.scrollHeight}}
