function customers(){return head('客户管理','每一段关系，都有完整的服务记录。',`<button class="btn" data-action="reset">重置演示</button>`)+`<section class="panel"><div class="toolbar"><input class="search" id="tableSearch" aria-label="搜索客户" placeholder="搜索客户姓名或标签" value="${esc(search)}"><span class="small muted">共 ${state.customers.length} 位样例客户</span></div><div class="table-wrap"><table><thead><tr><th>客户</th><th>服务阶段</th><th>当前需求</th><th>客户标签</th><th>操作</th></tr></thead><tbody>${state.customers.filter(c=>(c.name+c.tags.join('')).includes(search)).map(c=>`<tr><td><div class="flex">${avatar(c)}<div><b>${c.name}</b><p class="small muted" style="margin-top:4px">${c.source}</p></div></div></td><td><span class="tag">${c.stage}</span></td><td>${c.intent}</td><td>${c.tags.slice(0,2).map(t=>`<span class="tag gray" style="margin-right:5px">${t}</span>`).join('')}</td><td><button class="text-btn" data-open="${c.id}">进入服务 →</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">未找到符合条件的客户</td></tr>'}</tbody></table></div></section>`}
function retention(){return head('老客经营','在合适的时间，提供恰到好处的服务。',`<button class="btn primary" data-action="newtask">${icon('plus')} 新建跟进</button>`)+`<div class="cards">${[['待处理任务',pending(),'今日服务安排'],['补货跟进',state.tasks.filter(t=>t.type==='复购跟进'&&!t.done).length,'确认实际用量与意愿'],['购后回访',state.tasks.filter(t=>t.type==='购后回访'&&!t.done).length,'先解决使用问题'],['已完成任务',state.tasks.filter(t=>t.done).length,'处理结果已保留']].map(([l,n,d])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-number">${n}<small>项</small></div><div class="delta">${d}</div></div>`).join('')}</div><div class="onboarding">${icon('spark')}<span>跟进依据：购买记录＋用户沟通。补货时间仅作估计，联系前应确认实际余量，并尊重用户联系偏好。</span></div><div class="panel"><div class="panel-head between"><h2>客户跟进计划</h2><span class="small muted">小禾负责 · 本地保存</span></div><div class="tabs">${['全部','复购跟进','购后回访','已完成'].map(t=>`<button class="tab ${taskFilter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div>${taskRows(state.tasks.filter(t=>taskFilter==='已完成'?t.done:!t.done&&(taskFilter==='全部'||t.type===taskFilter)))}</div>`}
function orders(){return head('订单与售后','在接待和回访中，随时了解订单进展。')+`<div class="panel"><div class="panel-head between"><h2>客户关联订单</h2><span class="tag gray">全部为演示订单</span></div><div class="table-wrap"><table><thead><tr><th>订单 / 客户</th><th>商品</th><th>金额</th><th>订单状态</th><th>操作</th></tr></thead><tbody>${state.customers.filter(c=>c.order).map(c=>`<tr><td><b>${c.order.id}</b><p class="small muted" style="margin-top:5px">${c.name} · ${c.order.date}</p></td><td>${c.order.product}<p class="small muted" style="margin-top:5px">${c.order.spec}</p></td><td>¥${c.order.price}.00</td><td><span class="tag">${c.order.status}</span></td><td><button class="text-btn" data-order="${c.id}">订单详情</button>　<button class="text-btn" data-after="${c.id}">售后跟进</button></td></tr>`).join('')}</tbody></table></div></div>`}
const docs=[['产品比较与选购','益生菌与控达峰的产品定位、规格及使用方式对比。','产品资料 · 已审核'],['首次使用与保存','以商品包装标签为准，核对具体版本，处理常见保存问题。','服务问答 · 已审核'],['老客补货服务 SOP','确认余量与意愿，核查权益，尊重联系偏好，记录跟进结果。','服务流程 · 已审核'],['复杂问题处理','遇到疾病、用药、特殊人群或资料不足的问题，转交专业人员处理。','升级流程 · 已审核'],['商品规格与订单','演示益生菌30粒装399元，控达峰14袋装259元；均为样例价格。','演示商品 · v1.0'],['服务沟通原则','先理解需求，再提供资料；允许无适合产品，避免超出证据的承诺。','服务规范 · 已审核']];
function knowledge(){return head('产品与知识','每一条建议，都应有可追溯的依据。')+`<div class="onboarding">${icon('book')}<span>本页面为流程演示资料，不代表品牌真实产品标签、售价或经专业审核的使用建议。</span></div><div class="knowledge-grid">${docs.map(([title,desc,tag],i)=>`<section class="panel knowledge-card"><div class="product-icon">${icon(i%2?'book':'leaf')}</div><h2>${title}</h2><p>${desc}</p><div class="between"><span class="tag gray">${tag}</span><button class="text-btn" data-doc="${i}">阅读 →</button></div></section>`).join('')}</div>`}
function report(){return head('我的业绩','用服务过程与业务结果，一起衡量价值。')+stats()+`<div class="dashboard-grid"><section class="panel"><div class="panel-head between"><h2>服务与关联成交趋势</h2><span class="tag gray">静态演示基线</span></div><div class="metric-chart">${[46,61,51,73,63,86,77].map((n,i)=>`<div class="chart-col" style="height:${n}%"><b>${[12,16,13,19,16,22,20][i]}</b><span>10.${16+i}</span></div>`).join('')}</div><p class="small muted" style="padding:25px 25px 18px">演示图表仅用于展示统计结构，不反映真实业务效果。</p></section><section class="panel"><div class="panel-head"><h2>本次演示操作</h2><p class="small muted">根据你的实际操作更新</p></div><div class="funnel">${[['发送回复',Object.values(state.messages).flat().length],['完成任务',state.tasks.filter(t=>t.done).length],['新增任务',Math.max(0,state.tasks.length-4)],['客户备注',Object.keys(state.notes).length]].map(([l,n])=>`<div class="between" style="padding:12px 0;border-bottom:1px solid #eef2eb"><span class="muted">${l}</span><b>${n}</b></div>`).join('')}</div></section></div><div class="onboarding" style="margin-top:22px">${icon('chart')}<span>正式验收应通过对照实验，评估退款后的增量贡献利润；跟进后成交只表示业务关联。</span></div>`}
function renderPage(){return ({home,chat,customers,retention,orders,knowledge,report}[page]||home)()}
function navigate(p){page=p;search='';taskFilter='全部';aiReady=false;shell()}
function openCustomer(id){selected=Number(id);page='chat';aiReady=false;shell()}
function modal(title,body,confirmLabel,callback){const d=document.getElementById('dialog');d.innerHTML=`<h2>${title}</h2>${body}<div class="dialog-actions"><button class="btn" id="cancelModal">关闭</button>${confirmLabel?`<button class="btn primary" id="confirmModal">${confirmLabel}</button>`:''}</div>`;d.showModal();d.querySelector('#cancelModal').onclick=()=>d.close();if(confirmLabel)d.querySelector('#confirmModal').onclick=()=>callback(d);}
function newTask(){modal('创建跟进任务',`<p>记录下一步行动，按约定时间提供服务。</p><label>客户</label><select id="taskCustomer">${state.customers.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${c.name}</option>`).join('')}</select><label>任务类型</label><select id="taskType"><option>购后回访</option><option>复购跟进</option><option>咨询跟进</option><option>预约回访</option><option>售后跟进</option></select><label>计划时间</label><input id="taskTime" type="datetime-local" value="2026-10-23T10:00"><label>任务说明</label><textarea id="taskDesc" placeholder="例如：确认剩余用量和补货意愿"></textarea>`,'创建任务',d=>{const desc=d.querySelector('#taskDesc').value.trim(),time=d.querySelector('#taskTime').value;if(!desc||!time){toast('请填写计划时间与任务说明');return}state.tasks.push({id:Date.now(),cid:Number(d.querySelector('#taskCustomer').value),type:d.querySelector('#taskType').value,title:desc,desc:'手动创建的服务任务',time:time.replace('T',' '),priority:'待处理',done:false});state.events.unshift('新建任务：'+desc);save();d.close();shell();toast('跟进任务已创建')})}
function completeTask(id){const t=state.tasks.find(t=>t.id===Number(id));if(t.done){modal('任务处理结果',`<p>${esc(t.result)}</p>`,null);return}modal('完成任务 · '+customer(t.cid).name,`<p>${esc(t.title)}</p><label>处理结果</label><select id="result"><option>已解答，用户暂无其他问题</option><option>已确认补货意愿，等待用户下单</option><option>用户暂不需要，停止本轮跟进</option><option>需专业人员进一步处理</option><option>已确认后续联系时间</option></select><label>补充说明（选填）</label><textarea id="resultNote" placeholder="记录本次服务的实际结果"></textarea>`,'确认完成',d=>{t.done=true;t.result=d.querySelector('#result').value;const note=d.querySelector('#resultNote').value.trim();if(note)t.result+='；'+note;state.events.unshift(customer(t.cid).name+'：'+t.title+' · 已完成');save();d.close();shell();toast('任务已完成，处理结果已保存')})}
function showOrder(id){const c=customer(id),o=c.order;if(!o){toast('该客户暂无订单');return}modal('订单详情',`<p><b>${o.id}</b><br>客户：${c.name}<br>商品：${o.product}<br>规格：${o.spec}<br>样例实付：¥${o.price}.00<br>下单日期：${o.date}<br>状态：${o.status}<br><br>物流：演示快递 · 已签收<br>以上信息均为模拟数据。</p>`,'进入客户服务',d=>{d.close();openCustomer(id)})}
function action(a){const c=customer(selected);if(a==='newtask')return newTask();if(a==='draft'){const b=document.querySelector('[data-action="draft"]');b.disabled=true;b.textContent='正在整理建议…';setTimeout(()=>{if(page!=='chat'||selected!==c.id)return;document.getElementById('reply').value=c.draft;aiReady=true;b.disabled=false;b.innerHTML=icon('spark')+' 重新生成草稿';toast('模拟AI草稿已生成，请检查后发送')},650)}if(a==='send'){const el=document.getElementById('reply'),text=el.value.trim();if(!text)return toast('请先输入回复内容');(state.messages[c.id]??=[]).push(text);state.events.unshift(c.name+'：已发送模拟服务回复');save();shell();toast('回复已模拟发送，未联系真实客户')}if(a==='note')modal('客户备注 · '+c.name,`<label>服务备注</label><textarea id="note">${esc(state.notes[c.id]||'')}</textarea>`,'保存备注',d=>{const n=d.querySelector('#note').value.trim();if(n)state.notes[c.id]=n;else delete state.notes[c.id];save();d.close();shell();toast('客户备注已保存')});if(a==='profile')modal('客户档案 · '+c.name,`<p>${c.age} · ${c.source}<br>当前需求：${c.intent}<br>服务阶段：${c.stage}<br>历史记录：${c.history}<br><br><b>下一步建议（模拟AI）</b><br>${c.advice}<br><br>备注：${esc(state.notes[c.id]||'暂无备注')}</p>`,'查看关联订单',d=>{d.close();showOrder(c.id)});if(a==='order')showOrder(selected);if(a==='product')modal('产品比较 · 演示资料',`<p><b>益生菌产品</b><br>菌群相关营养补充方向，样例规格30粒装。<br><br><b>控达峰 Papone</b><br>餐后管理方向固体饮料，样例规格14袋装。<br><br>实际配料、使用方式、适用人群与价格以产品标签和结算页面为准。本资料仅用于界面演示。</p>`,null);if(a==='help')modal('三分钟演示路线',`<p>① 在今日工作中，打开张女士的补货跟进。<br>② 点击「AI辅助回复」，检查并编辑草稿。<br>③ 点击「发送」，查看模拟会话。<br>④ 创建回访任务，进入「老客经营」完成任务并记录结果。<br>⑤ 在「我的业绩」查看本次操作统计。<br><br>支持客户搜索、订单查询、知识阅读与备注。本演示使用预设AI回复和浏览器本地存储，不接真实渠道。</p>`,null);if(a==='reset')modal('重置演示数据',`<p>清除本浏览器保存的模拟回复、任务处理结果和备注，恢复初始样例。</p>`,'确认重置',d=>{state=structuredClone(initial);save();d.close();shell();toast('已恢复初始演示数据')})}
function bind(){document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>navigate(e.dataset.nav));document.querySelectorAll('[data-open],[data-person]').forEach(e=>e.onclick=()=>openCustomer(e.dataset.open||e.dataset.person));document.querySelectorAll('[data-filter]').forEach(e=>e.onclick=()=>{taskFilter=e.dataset.filter;shell()});document.querySelectorAll('[data-action]').forEach(e=>e.onclick=()=>action(e.dataset.action));document.querySelectorAll('[data-complete]').forEach(e=>e.onclick=()=>completeTask(e.dataset.complete));document.querySelectorAll('[data-order]').forEach(e=>e.onclick=()=>showOrder(Number(e.dataset.order)));document.querySelectorAll('[data-after]').forEach(e=>e.onclick=()=>{selected=Number(e.dataset.after);newTask();document.getElementById('taskType').value='售后跟进'});document.querySelectorAll('[data-doc]').forEach(e=>e.onclick=()=>{const doc=docs[e.dataset.doc];modal(doc[0],`<p>${doc[1]}<br><br>资料类型：${doc[2]}<br>版本：演示 v1.0<br>用途：顾问工作台流程演示<br><br>正式上线前需要专业人员审核产品资料，并关联实际产品版本。</p>`,null)});const cs=document.getElementById('chatSearch');if(cs)cs.oninput=()=>{document.getElementById('people').innerHTML=people(cs.value.trim());document.querySelectorAll('[data-person]').forEach(e=>e.onclick=()=>openCustomer(e.dataset.person))};const ts=document.getElementById('tableSearch');if(ts)ts.oninput=()=>{const pos=ts.selectionStart;search=ts.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{shell();const t=document.getElementById('tableSearch');t.focus();t.setSelectionRange(pos,pos)},180)}}
shell();
